document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='edit-proxy')window.editProxy(id);else if(a==='test-proxy')window.testProxy(id);else if(a==='delete-proxy')window.deleteProxy(id);else if(a==='account-dashboard')window.accountDash(id);else if(a==='proxy-test')window.proxyTest(id);else if(a==='account-back')load('accounts');else if(a==='edit-account')window.editAccount(id);else if(a==='account-refresh')window.accountRefresh(id);else if(a==='account-preflight')window.accountPreflight(id);else if(a==='delete-account')window.deleteAccount(id);else if(a==='edit-settings')openForm('settings')});
