function statusClass(v){v=String(v||'').toLowerCase();return v==='healthy'?'statusHealthy':v==='degraded'?'statusDegraded':'statusDown'}
function proxyCard(r){const rotating=(r.adapter||'generic')==='generic',ipLabel=rotating?'Current sample IP':'Exit IP',countryLabel=rotating?'Sample country':'Country',asnLabel=rotating?'Sample ASN':'ASN';return '<div class="card proxyCard"><div class="accountCardTop"><div><div class="accountName">'+esc(r.name)+'</div><div class="muted">'+esc(r.host)+':'+esc(r.port)+'</div></div><span class="statusBadge '+statusClass(r.status)+'">'+esc(r.status)+'</span></div><div class="proxyMeta"><span>Type</span><span>'+esc(r.type)+'</span><span>Mode</span><span><span class="badge '+(rotating?'good':'')+'">'+esc(rotating?'Rotating':'Fixed')+'</span></span><span>'+ipLabel+'</span><span>'+esc(r.exit_ip||'—')+'</span><span>'+countryLabel+'</span><span>'+esc(r.country||'—')+'</span><span>'+asnLabel+'</span><span>'+esc(r.asn||'—')+'</span><span>Latency</span><span>'+esc(r.latency_ms? r.latency_ms+' ms':'—')+'</span><span>Failures</span><span>'+esc(r.failure_count||0)+'</span><span>Last check</span><span>'+esc(formatDate(r.last_checked_at))+'</span></div>'+(rotating?'<p class="muted">Sample identity is from the latest proxy health check and may change on the next connection. Each account tracks its own current exit identity.</p>':'')+'<div class="cardActions"><button class="small" data-action="test-proxy" data-id="'+r.id+'">Test</button><button class="small ghost" data-action="edit-proxy" data-id="'+r.id+'">Edit</button><button class="small danger" data-action="delete-proxy" data-id="'+r.id+'">Delete</button></div></div>'}
let proxyRefreshTimer=setInterval(()=>{if(token&&current==='proxies'&&!$('#modal').open)load('proxies')},15000);

function parseMinutesExpr(v){v=String(v||'').trim();if(!/^[0-9.]+(?:\s*\*\s*[0-9.]+)*$/.test(v))throw Error('Build spacing must be minutes, e.g. 30 or 6*60');const n=v.split('*').reduce((a,x)=>a*Number(x.trim()),1);if(!Number.isFinite(n)||n<1||n>525600)throw Error('Build spacing is out of range');return Math.round(n)}function formatDate(v){if(!v)return '—';const d=new Date(v);return isNaN(d)?String(v):new Intl.DateTimeFormat('en-GB',{calendar:'gregory',timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(d)}let toastTimer;function toast(message,type='ok'){const el=$('#toast');if(!el)return;clearTimeout(toastTimer);el.textContent=message;el.className='toast '+type;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,4500)}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action="request-rotation"]');if(!b)return;const id=b.dataset.id,old=b.textContent;b.disabled=true;b.textContent='Requesting...';try{await api('/api/v1/accounts/'+id+'/password-rotation/request',{method:'POST',body:'{}'});await accountDash(id,{preserveHash:true})}catch(err){alert(err.message||'Password rotation request failed')}finally{b.disabled=false;b.textContent=old}});

// DOM-safe login credential editor: mounted after Account Dashboard renders.
(function(){
 const original=window.accountDash;
 if(typeof original!=='function'||window.__loginEditorWrapped)return;
 window.__loginEditorWrapped=true;
 window.accountDash=async function(id,opt){
  const out=await original(id,opt);
  const heads=[...document.querySelectorAll('.card.section h3')];
  const h=heads.find(x=>x.textContent.trim()==='DigitalOcean Login');
  if(!h)return out;
  const card=h.closest('.card'); if(!card||card.querySelector('.loginCredentialEditor'))return out;
  const box=document.createElement('div'); box.className='loginCredentialEditor';
  const email=document.createElement('input'); email.type='email';email.className='loginCredentialEmail';email.autocomplete='username';email.placeholder='DigitalOcean login email';
  const pass=document.createElement('input');pass.type='password';pass.className='loginCredentialPassword';pass.autocomplete='new-password';pass.placeholder='Password (empty keeps stored password)';
  const show=document.createElement('button');show.type='button';show.className='small';show.textContent='Show';show.onclick=()=>{const v=pass.type==='password';pass.type=v?'text':'password';show.textContent=v?'Hide':'Show'};
  const save=document.createElement('button');save.type='button';save.className='small';save.textContent='Save Login Credentials';save.onclick=async()=>{const old=save.textContent;save.disabled=true;save.textContent='Saving...';try{await api('/api/v1/accounts/'+id+'/login-credentials',{method:'PUT',body:JSON.stringify({email:email.value.trim(),password:pass.value})});pass.value='';await window.accountDash(id,{preserveHash:true})}catch(e){alert(e.message||'Unable to save login credentials')}finally{save.disabled=false;save.textContent=old}};
  box.append(email,pass,show,save); h.after(box); return out;
 };
})();

