(function(){
 if(window.__buildActivityInstalled)return;window.__buildActivityInstalled=true;
 const oldPages=pages; if(!pages.some(x=>x[0]==='build-activity'))pages.splice(3,0,['build-activity','Build Activity']);
 const oldLoad=window.load||load;
 const renderBuild=async()=>{current='build-activity';sessionStorage.setItem('page',current);$('#title').textContent='Build Activity';$('#primaryAction').hidden=true;const c=$('#content');c.innerHTML='<p class="muted">Loading build activity...</p>';try{const [d,errs]=await Promise.all([api('/api/v1/build-activity'),api('/api/v1/provision-errors').catch(()=>[])]);const active=d.filter(x=>!['READY','FAILED'].includes(String(x.state).toUpperCase())).length;c.innerHTML='<div class="grid">'+stat('Active builds',active)+stat('Recent records',d.length)+stat('SSH / install error families',errs.length)+'</div><div class="card section"><h3>Server build process</h3><p class="muted">Live view — refreshes every 5 seconds. Open Details for SSH stages, script phases and retry history.</p>'+(d.length?'<div class="tableWrap"><table class="table"><thead><tr><th>Account</th><th>State</th><th>Step</th><th>Attempt</th><th>Detail</th><th>Updated</th><th>Diagnostics</th></tr></thead><tbody>'+d.map(x=>'<tr><td>'+esc(x.account)+'</td><td><span class="badge '+(x.state==='READY'?'good':x.state==='FAILED'?'bad':'')+'">'+esc(x.state)+'</span></td><td>'+esc(x.step)+'</td><td>'+esc(x.attempt)+'</td><td>'+esc(x.error||x.message||'—')+'</td><td>'+esc(formatDate(x.updated_at))+'</td><td><button class="small" data-build-detail="'+esc(x.id)+'">Details</button></td></tr>').join('')+'</tbody></table></div>':'<p class="muted">No build activity yet.</p>')+'</div><div class="card section"><h3>SSH / Installation Error Intelligence</h3><p class="muted">Unknown errors are grouped by a stable sanitized fingerprint so recurring server problems remain visible.</p>'+(errs.length?'<div class="tableWrap"><table class="table"><thead><tr><th>Class</th><th>Code</th><th>Fingerprint</th><th>Occurrences</th><th>Deployments</th><th>Accounts</th><th>Last stage</th><th>Last seen</th></tr></thead><tbody>'+errs.map(x=>'<tr title="'+esc(x.last_error||'')+'"><td>'+esc(x.error_class||'unknown')+'</td><td>'+esc(x.error_code||'—')+'</td><td><code>'+esc(x.fingerprint)+'</code></td><td>'+esc(x.occurrences)+'</td><td>'+esc(x.affected_deployments)+'</td><td>'+esc(x.affected_accounts)+'</td><td>'+esc((x.last_step||'')+(x.last_substep?' / '+x.last_substep:''))+'</td><td>'+esc(formatDate(x.last_seen))+'</td></tr>').join('')+'</tbody></table></div>':'<p class="muted">No SSH or installation errors recorded.</p>')+'</div>';c.querySelectorAll('[data-build-detail]').forEach(b=>b.onclick=()=>openProvisionDetail(b.dataset.buildDetail))}catch(e){c.innerHTML='<p class="error">'+esc(e.message)+'</p>'}};
 window.openProvisionDetail=async id=>{try{const d=await api('/api/v1/build-activity/'+id+'/provision');$('#modalTitle').textContent='SSH & Installation Diagnostics';const steps=(d.steps||[]).map(x=>'<tr><td>'+esc(x.step)+'</td><td>'+esc(x.attempts)+'</td><td>'+esc(x.terminal?'Terminal':x.next_retry_at?'Retry wait':'Active / completed')+'</td><td>'+esc(x.last_error||'—')+'</td></tr>').join(''),events=(d.events||[]).map(x=>'<tr><td>'+esc(formatDate(x.created_at))+'</td><td>'+esc(x.step)+'</td><td>'+esc(x.substep||'—')+'</td><td>'+esc(x.state)+'</td><td>'+esc(x.error_code||'—')+'</td><td>'+esc(x.exit_code??'—')+'</td><td>'+esc(x.duration_ms)+' ms</td><td title="'+esc(x.error||x.stderr_tail||x.stdout_tail||'')+'"><code>'+esc(x.fingerprint||'—')+'</code></td></tr>').join('');const ins=d.installer||{};const installer=Object.keys(ins).length?'<h4>Installer</h4><div class="kv"><span>Name / version</span><span>'+esc(ins.name+' v'+ins.version)+'</span><span>State</span><span>'+esc(ins.state)+'</span><span>Manifest SHA256</span><span><code>'+esc(ins.sha256)+'</code></span><span>Last error</span><span>'+esc(ins.last_error||'—')+'</span></div>':'';const rd=d.readiness||{};const readiness=Object.keys(rd).length?'<h4>Server readiness</h4><div class="kv"><span>Status</span><span>'+esc(rd.status)+'</span><span>OS</span><span>'+esc((rd.os_id||'')+' '+(rd.os_version||''))+'</span><span>Architecture</span><span>'+esc(rd.architecture||'—')+'</span><span>CPU / RAM</span><span>'+esc((rd.cpu_count||0)+' CPU / '+(rd.memory_mb||0)+' MB')+'</span><span>Disk free</span><span>'+esc((rd.disk_free_mb||0)+' MB')+'</span><span>Package manager</span><span>'+esc(rd.package_manager||'—')+'</span><span>Package health</span><span>'+esc(rd.package_health||'—')+'</span><span>DNS / HTTPS</span><span>'+esc((rd.dns_ok?'OK':'FAIL')+' / '+(rd.outbound_https_ok?'OK':'FAIL'))+'</span><span>Time sync</span><span>'+esc(rd.time_sync||'unknown')+'</span><span>Reboot required</span><span>'+esc(rd.reboot_required?'Yes':'No')+'</span></div><div class="tableWrap"><table class="table"><thead><tr><th>Issue</th><th>Severity</th><th>Decision</th><th>State</th><th>Detail</th></tr></thead><tbody>'+((rd.issues||[]).map(i=>'<tr><td>'+esc(i.code)+'</td><td>'+esc(i.severity)+'</td><td>'+esc(i.action)+'</td><td>'+esc(i.state)+'</td><td>'+esc(i.detail||'—')+'</td></tr>').join('')||'<tr><td colspan="5">No readiness issues</td></tr>')+'</tbody></table></div>':'';$('#modalFields').innerHTML='<div class="kv"><span>State</span><span>'+esc(d.state)+'</span><span>Current step</span><span>'+esc(d.current_step)+'</span><span>Run attempt</span><span>'+esc(d.attempt)+'</span><span>Last error</span><span>'+esc(d.last_error||'—')+'</span></div>'+readiness+installer+'<h4>Step attempts</h4><div class="tableWrap"><table class="table"><thead><tr><th>Step</th><th>Attempts</th><th>Status</th><th>Last error</th></tr></thead><tbody>'+steps+'</tbody></table></div><h4>SSH / Script timeline</h4><div class="tableWrap"><table class="table"><thead><tr><th>Time</th><th>Step</th><th>Stage / phase</th><th>State</th><th>Error code</th><th>Exit</th><th>Duration</th><th>Fingerprint</th></tr></thead><tbody>'+events+'</tbody></table></div>';$('#modalError').textContent='';$('#modalSubmit').hidden=true;$('#modal').addEventListener('close',()=>{$('#modalSubmit').hidden=false},{once:true});$('#modal').showModal()}catch(e){alert(e.message)}};
 const baseLoad=load; window.load=load=async function(page){if(page==='build-activity')return renderBuild();return baseLoad(page)};
 setInterval(()=>{if(current==='build-activity'&&!document.hidden)renderBuild()},5000);
})();
